*** Begin Patch
*** Add File: out/plan_1.json
+{
+  "initial_plan": {
+    "answerability": "partly: the file can show counts of police-reported crashes by time of day, but without traffic, travel, or person-exposure denominators it cannot establish whether a street user is more likely to crash at night",
+    "metric": "number of police-reported crashes",
+    "denominator": "none; counts crash rows",
+    "population": "all crashes with a nonmissing crash_date, assigned to its calendar year; crashes with an unclassifiable crash_time remain in an Unknown time group",
+    "filters": ["nonmissing crash_date", "include all available calendar years; final handling of partial years pending data check"],
+    "years": "all calendar years represented by nonmissing crash_date; identify exact range and partial years in the data check",
+    "grouping": ["calendar year of crash_date", "Night (20:00–05:59), Day (06:00–19:59), or Unknown time if crash_time is missing/unclassifiable"]
+  }
+}
*** Add File: out/plan_2.json
+{
+  "initial_plan": {
+    "answerability": "partly: the file can compare the share of reported crashes involving recorded injury or death by time of day, a crash-severity measure, but cannot establish crash risk per trip or per person because exposure denominators are absent",
+    "metric": "share of classifiable police-reported crashes with at least one person injured or killed",
+    "denominator": "police-reported crash rows with nonmissing values in all four total/person, pedestrian, cyclist and motorist injury/death columns are not needed here; use the total number_of_persons_injured and number_of_persons_killed fields only, so denominator is crashes with both total fields present",
+    "population": "all crashes with a nonmissing crash_date in the years selected after the data check; missing/unclassifiable crash_time is retained as Unknown; crashes missing either total injury or total death count are not classifiable and excluded from the denominator",
+    "filters": ["nonmissing crash_date", "both number_of_persons_injured and number_of_persons_killed nonmissing", "include all available calendar years; final handling of partial years pending data check"],
+    "years": "all calendar years represented by nonmissing crash_date; identify exact range and partial years in the data check",
+    "grouping": ["calendar year of crash_date", "Night (20:00–05:59), Day (06:00–19:59), or Unknown time if crash_time is missing/unclassifiable"]
+  }
+}
